// Outline JSON parsen und Sektionen als einzelne Items aufbereiten
const input = $input.all()[0].json;
let outline;
try {
  outline = typeof input.outline_json === 'string' ? JSON.parse(input.outline_json) : input.outline_json;
} catch(e) {
  // Fallback: versuche aus Markdown-Block zu parsen
  const match = (input.outline_json || '').match(/```(?:json)?\s*([\s\S]*?)```/);
  outline = match ? JSON.parse(match[1].trim()) : { sections: [], title_suggestion: input.keyword };
}

const sections = outline.sections || [];
const totalSections = sections.length;

// Jede Sektion als separates Item für den Loop
return sections.map((section, index) => ({
  json: {
    section_index: index,
    total_sections: totalSections,
    h2: section.h2 || '',
    h3_subsections: JSON.stringify(section.h3_subsections || []),
    infographic: JSON.stringify(section.infographic || null),
    key_points: JSON.stringify((section.h3_subsections || []).flatMap(s => s.key_points || [])),
    wdf_idf_terms_section: JSON.stringify((section.h3_subsections || []).flatMap(s => s.wdf_idf_terms || [])),
    internal_link: JSON.stringify((section.h3_subsections || []).map(s => s.internal_link).filter(Boolean)),
    title_suggestion: outline.title_suggestion || '',
    faq_section: JSON.stringify(outline.faq_section || []),
    all_internal_links: JSON.stringify(outline.internal_links || [])
  }
}));

// Claude-Antwort extrahieren
const items = $input.all();
return items.map((item, index) => {
  const content = item.json.content?.[0]?.text || item.json.choices?.[0]?.message?.content || '';
  return {
    json: {
      section_index: index,
      section_content: content
    }
  };
});

// Alle Sektionen zu einem Gesamtartikel zusammenfügen
const sections = $input.all()
  .sort((a, b) => a.json.section_index - b.json.section_index)
  .map(item => item.json.section_content);

const fullDraft = sections.join('\n\n---\n\n');

return [{ json: { full_draft: fullDraft, section_count: sections.length } }];

// Finalen Artikel extrahieren
const response = $input.all()[0].json;
const finalArticle = response.content?.[0]?.text || '';

return [{ json: { final_article: finalArticle } }];

// FAQ-Sektion aus dem Outline generieren (falls vorhanden)
const outlineJson = $('Extract Input Data').item.json.outline_json;
let outline;
try {
  outline = typeof outlineJson === 'string' ? JSON.parse(outlineJson) : outlineJson;
} catch(e) { outline = { faq_section: [] }; }

const faqItems = outline.faq_section || [];
if (faqItems.length === 0) {
  return [{ json: { faq_markdown: '', has_faq: false } }];
}

let faqMd = '\n\n## Häufig gestellte Fragen (FAQ)\n\n';
for (const faq of faqItems) {
  faqMd += `### ${faq.question}\n\n${faq.answer_outline}\n\n`;
}

return [{ json: { faq_markdown: faqMd, has_faq: true, faq_count: faqItems.length } }];

// Meta-Daten parsen
const response = $input.all()[0].json;
const content = response.content?.[0]?.text || '';

let rawMeta;
try {
  rawMeta = JSON.parse(content);
} catch(e) {
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    try { rawMeta = JSON.parse(jsonMatch[1].trim()); } catch(e2) {}
  }
  if (!rawMeta) {
    const braceMatch = content.match(/\{[\s\S]*\}/);
    if (braceMatch) try { rawMeta = JSON.parse(braceMatch[0]); } catch(e3) {}
  }
}

// Find the first variant - handles variant_1, variante_1, Variante_1, etc.
let meta = null;
if (rawMeta) {
  // Try direct fields first
  if (rawMeta.meta_title) {
    meta = rawMeta;
  } else {
    // Search for any variant key
    for (const key of Object.keys(rawMeta)) {
      const val = rawMeta[key];
      if (val && typeof val === 'object' && val.meta_title) {
        meta = val;
        break;
      }
    }
  }
}

if (!meta) {
  const keyword = $('Extract Input Data').item.json.keyword || '';
  meta = {
    meta_title: keyword,
    meta_description: '',
    url_slug: keyword.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
    focus_keyword: keyword
  };
}

// Clean up
meta.meta_title = meta.meta_title || '';
meta.meta_description = meta.meta_description || '';
meta.url_slug = meta.url_slug || '';
meta.focus_keyword = meta.focus_keyword || $('Extract Input Data').item.json.keyword || '';

