    requests.push({
      updateParagraphStyle: {
        range: { startIndex: currentIndex, endIndex: currentIndex + blockLen },
        paragraphStyle: { namedStyleType: block.style },
        fields: 'namedStyleType'
      }
    });
  }

  // Bullet list
  if (block.is_bullet) {
    requests.push({
      createParagraphBullets: {
        range: { startIndex: currentIndex, endIndex: currentIndex + blockLen },
        bulletPreset: 'BULLET_DISC_CIRCLE_SQUARE'
      }
    });
  }

  if (block.is_numbered) {
    requests.push({
      createParagraphBullets: {
        range: { startIndex: currentIndex, endIndex: currentIndex + blockLen },
        bulletPreset: 'NUMBERED_DECIMAL_NESTED'
      }
    });
  }

  // Bold ranges
  for (const br of block.bold_ranges) {
    requests.push({
      updateTextStyle: {
        range: { startIndex: currentIndex + br.start, endIndex: currentIndex + br.end },
        textStyle: { bold: true },
        fields: 'bold'
      }
    });
  }

  // Italic ranges
  for (const ir of block.italic_ranges) {
    requests.push({
      updateTextStyle: {
        range: { startIndex: currentIndex + ir.start, endIndex: currentIndex + ir.end },
        textStyle: { italic: true },
        fields: 'italic'
      }
    });
  }

  // Links
  for (const link of block.links) {
    requests.push({
      updateTextStyle: {
        range: { startIndex: currentIndex + link.start, endIndex: currentIndex + link.end },
        textStyle: { link: { url: link.url } },
        fields: 'link'
      }
    });
  }

  currentIndex += blockLen;
