  let style = 'NORMAL_TEXT';
  let cleanLine = line;
  if (line.startsWith('#### ')) { style = 'HEADING_4'; cleanLine = line.substring(5); }
  else if (line.startsWith('### ')) { style = 'HEADING_3'; cleanLine = line.substring(4); }
  else if (line.startsWith('## ')) { style = 'HEADING_2'; cleanLine = line.substring(3); }
  else if (line.startsWith('# ')) { style = 'HEADING_1'; cleanLine = line.substring(2); }

  // Bullets
  let is_bullet = false;
  let is_numbered = false;
  if (cleanLine.match(/^[-*]\s/)) { is_bullet = true; cleanLine = cleanLine.replace(/^[-*]\s/, ''); }
  if (cleanLine.match(/^\d+\.\s/)) { is_numbered = true; cleanLine = cleanLine.replace(/^\d+\.\s/, ''); }

  // Find bold ranges **text**
  const bold_ranges = [];
  let processedText = '';
  let pos = 0;
  let tempLine = cleanLine;

  // Process links [text](url)
  const links = [];
  tempLine = tempLine.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (match, text, url, offset) => {
    return text; // Replace with just the link text, we'll add the link style later
  });

  // Re-find links with positions after other processing
  // First pass: extract bold
  let finalText = '';
  let boldRegex = /\*\*(.+?)\*\*/g;
  let lastIdx = 0;
  let boldMatch;
  while ((boldMatch = boldRegex.exec(tempLine)) !== null) {
    finalText += tempLine.substring(lastIdx, boldMatch.index);
    const boldStart = finalText.length;
    finalText += boldMatch[1];
    bold_ranges.push({ start: boldStart, end: finalText.length });
    lastIdx = boldMatch.index + boldMatch[0].length;
  }
  finalText += tempLine.substring(lastIdx);

  // Extract italic *text*
  const italic_ranges = [];
  let italicText = '';
  let italicRegex = /(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/g;
  lastIdx = 0;
  let italicMatch;
  let tempFinal = finalText;
  finalText = '';
  while ((italicMatch = italicRegex.exec(tempFinal)) !== null) {
    finalText += tempFinal.substring(lastIdx, italicMatch.index);
    const italicStart = finalText.length;
    finalText += italicMatch[1];
    italic_ranges.push({ start: italicStart, end: finalText.length });
    lastIdx = italicMatch.index + italicMatch[0].length;
  }
  finalText += tempFinal.substring(lastIdx);

  // Find links in the original line and map to positions in finalText
  const linkRegex = /\[([^\]]+)\]\(([^)]+)\)/g;
  let linkMatch;
  while ((linkMatch = linkRegex.exec(cleanLine)) !== null) {
    const linkText = linkMatch[1];
    const linkUrl = linkMatch[2];
    const linkPos = finalText.indexOf(linkText);
    if (linkPos >= 0) {
      links.push({ start: linkPos, end: linkPos + linkText.length, url: linkUrl });
    }
  }

  blocks.push({
    text: finalText + '\n',
    style: style,
    bold_ranges: bold_ranges,
    italic_ranges: italic_ranges,
    links: links,
    is_bullet: is_bullet,
    is_numbered: is_numbered
  });
}

// Build Google Docs API requests
// First: insert all text at once, then apply formatting
let fullText = blocks.map(b => b.text).join('');
const requests = [];

// 1. Insert all text at index 1
requests.push({
  insertText: {
    location: { index: 1 },
    text: fullText
  }
});

// 2. Apply paragraph styles (headings, bullets)
let currentIndex = 1;
for (const block of blocks) {
  const blockLen = block.text.length;

  if (block.style !== 'NORMAL_TEXT') {
    requests.push({
      updateParagraphStyle: {
        range: { startIndex: currentIndex, endIndex: currentIndex + blockLen },
        paragraphStyle: { namedStyleType: block.style },
        fields: 'namedStyleType'
      }
    });
  }

  // Bullet list
  if (block.is_bullet) {
    requests.push({
      createParagraphBullets: {
        range: { startIndex: currentIndex, endIndex: currentIndex + blockLen },
        bulletPreset: 'BULLET_DISC_CIRCLE_SQUARE'
      }
    });
  }

  if (block.is_numbered) {
    requests.push({
      createParagraphBullets: {
        range: { startIndex: currentIndex, endIndex: currentIndex + blockLen },
        bulletPreset: 'NUMBERED_DECIMAL_NESTED'
      }
    });
  }

  // Bold ranges
  for (const br of block.bold_ranges) {
    requests.push({
      updateTextStyle: {
        range: { startIndex: currentIndex + br.start, endIndex: currentIndex + br.end },
        textStyle: { bold: true },
        fields: 'bold'
      }
    });
  }

  // Italic ranges
  for (const ir of block.italic_ranges) {
    requests.push({
      updateTextStyle: {
        range: { startIndex: currentIndex + ir.start, endIndex: currentIndex + ir.end },
        textStyle: { italic: true },
        fields: 'italic'
      }
    });
  }

  // Links
  for (const link of block.links) {
    requests.push({
      updateTextStyle: {
        range: { startIndex: currentIndex + link.start, endIndex: currentIndex + link.end },
        textStyle: { link: { url: link.url } },
        fields: 'link'
      }
    });
  }

  currentIndex += blockLen;
}

return [{
  json: {
    doc_id: docId,
    doc_url: docUrl,
    requests: requests
  }
}];

// Zusammenfassung
const meta = $('Parse Meta & Assemble Final').item.json.meta;
const wordCount = $('Parse Meta & Assemble Final').item.json.word_count;
const docUrl = $('Prepare Doc Content').item.json.doc_url;
const keyword = $('Extract Input Data').item.json.keyword;

return [{
  json: {
    success: true,
    keyword: keyword,
    meta_title: meta.meta_title,
    meta_description: meta.meta_description,
    url_slug: meta.url_slug,
    word_count: wordCount,
    google_doc_url: docUrl,
    message: `Content für "${keyword}" erstellt (${wordCount} Wörter). Doc: ${docUrl}`
  }
}];

// WDF*IDF Abdeckungsprüfung für den gesamten Beitrag
const article = $('Extract Final Article').item.json.final_article.toLowerCase();
const wdfTermsRaw = $('Extract Input Data').item.json.wdf_idf_terms_json;
let wdfTerms;
try {
  wdfTerms = typeof wdfTermsRaw === 'string' ? JSON.parse(wdfTermsRaw) : wdfTermsRaw;
} catch(e) { wdfTerms = []; }

if (!wdfTerms || wdfTerms.length === 0) {
  return [{ json: { wdf_idf_check: 'Keine WDF*IDF Terme vorhanden', coverage_pct: 0, missing_terms: [], found_terms: [] } }];
}

const found = [];
const missing = [];
for (const t of wdfTerms) {
  const term = (t.term || t).toLowerCase();
  if (article.includes(term)) {
    found.push({ term, score: t.score || 0 });
  } else {
    missing.push({ term, score: t.score || 0 });
  }
}

const coveragePct = Math.round((found.length / wdfTerms.length) * 100);

// Top 15 fehlende Terme (nach Score sortiert)
const topMissing = missing.sort((a, b) => b.score - a.score).slice(0, 15);

return [{
  json: {
    coverage_pct: coveragePct,
    found_count: found.length,
    total_terms: wdfTerms.length,
    missing_count: missing.length,
    top_missing_terms: topMissing.map(t => `${t.term} (${t.score})`).join(', '),
    found_terms: found.map(t => t.term),
    needs_optimization: coveragePct < 60
  }
}];

// Optimierten Artikel extrahieren und als final_article ersetzen
const response = $input.all()[0].json;
const optimizedArticle = response.content?.[0]?.text || $('Extract Final Article').item.json.final_article;

// Überschreibe final_article für die nachfolgenden Nodes
return [{ json: { final_article: optimizedArticle } }];

// Merge: nimmt optimierten Artikel falls vorhanden, sonst Original
const items = $input.all();
// Der letzte Input ist der richtige (entweder optimiert oder original)
const finalArticle = items[items.length - 1].json.final_article 
  || $('Extract Final Article').item.json.final_article;

return [{ json: { final_article: finalArticle } }];

// GEO-optimierten Artikel extrahieren
const response = $input.all()[0].json;
const geoArticle = response.content?.[0]?.text || $('Merge Article (Original or Optimized)').item.json.final_article;

return [{ json: { final_article: geoArticle } }];
